# %% ../notebooks/14_controlled_processes.ipynb #controlled-fn-scalar
def _scalar(name, value, *, minimum=None, positive=False):
    a = _real_array(value, name)
    if a.ndim != 0 or not np.isfinite(a):
        raise ValueError(f"{name} must be a finite real scalar")
    result = float(a)
    if positive and result <= 0 or minimum is not None and result < minimum:
        raise ValueError(
            f'{name} must be {"positive" if positive else f">= {minimum}"}'
        )
    return result


# %% ../notebooks/14_controlled_processes.ipynb #controlled-fn-finite
def _finite(value, purpose):
    a = np.asarray(value, dtype=float)
    if not np.isfinite(a).all():
        raise ValueError(
            f"{purpose} overflowed; reduce horizon, rates, scales or time step"
        )
    return a


# %% ../notebooks/14_controlled_processes.ipynb #controlled-fn-exp
def _exp(value, purpose):
    with np.errstate(over="ignore", under="ignore", invalid="ignore"):
        result = np.exp(value)
    _finite(result, purpose)
    if np.any(result == 0):
        raise ValueError(
            f"{purpose} underflowed; reduce horizon, rates, scales or time step"
        )
    return result


# %% ../notebooks/14_controlled_processes.ipynb #controlled-fn-log-cumulant
def _log_cumulant(k, mu, sigma, rate, jump_mean, jump_sigma, dt):
    """Physical-measure Merton convention: E[S(t+dt)/S(t)] = exp(mu*dt)."""
    with np.errstate(over="ignore", invalid="ignore"):
        kappa = np.expm1(jump_mean + 0.5 * jump_sigma**2)
        value = (
            k * (mu - 0.5 * sigma**2 - rate * kappa)
            + 0.5 * k * k * sigma**2
            + rate * np.expm1(k * jump_mean + 0.5 * k * k * jump_sigma**2)
        ) * dt
    return _finite(value, "Log-return cumulant")


# %% ../notebooks/14_controlled_processes.ipynb #controlled-shared-joint-vector
def _vector(value, name, d, *, minimum=None, positive=False):
    a = _real_array(value, name)
    if a.ndim == 0:
        a = np.full(d, float(a))
    if a.shape != (d,) or not np.isfinite(a).all():
        raise ValueError(
            f"{name} must be a finite scalar or vector of length n_targets"
        )
    if positive and np.any(a <= 0) or minimum is not None and np.any(a < minimum):
        raise ValueError(
            f'{name} must be {"positive" if positive else f">= {minimum}"}'
        )
    return a


# %% ../notebooks/14_controlled_processes.ipynb #controlled-shared-joint-correlation
def _correlation(value, d, name="correlation", *, definite=False):
    a = _real_array(value, name)
    if a.ndim == 0:
        rho = float(a)
        if not np.isfinite(rho) or not (-1 / (d - 1) if d > 1 else -1) <= rho <= 1:
            raise ValueError(f"{name}: invalid equicorrelation for {d} targets")
        a = np.full((d, d), rho)
        np.fill_diagonal(a, 1.0)
    if (
        a.shape != (d, d)
        or not np.isfinite(a).all()
        or not np.allclose(a, a.T, atol=1e-12, rtol=0)
        or not np.allclose(np.diag(a), 1.0, atol=1e-12, rtol=0)
    ):
        raise ValueError(
            f"{name} must be a symmetric correlation matrix of shape ({d}, {d})"
        )
    a = (a + a.T) / 2
    np.fill_diagonal(a, 1.0)
    eigenvalues = np.linalg.eigvalsh(a)
    if eigenvalues.min() < -1e-12 or definite and eigenvalues.min() <= 1e-12:
        raise ValueError(
            f'{name} must be positive {"definite for multivariate regime filtering" if definite else "semidefinite"}'
        )
    # Keep validated entries stable across manifest replay; factorization
    # clips only numerical eigenvalue roundoff in the separate sampler.
    return (a + a.T) / 2


# %% ../notebooks/14_controlled_processes.ipynb #controlled-shared-joint-regime-vector
def _regime_vector(value, name, k, d, *, nonnegative=False, positive=False):
    a = _real_array(value, name)
    if a.shape == (k,):
        a = np.repeat(a[:, None], d, axis=1)
    if a.shape != (k, d) or not np.isfinite(a).all():
        raise ValueError(f"{name} must have shape (regimes,) or (regimes, n_targets)")
    if nonnegative and np.any(a < 0) or positive and np.any(a <= 0):
        raise ValueError(f'{name} must be {"positive" if positive else "nonnegative"}')
    return a


# %% ../notebooks/14_controlled_processes.ipynb #controlled-shared-joint-factor
def _factor(matrix):
    values, vectors = np.linalg.eigh(matrix)
    return vectors * np.sqrt(np.maximum(values, 0.0))


# %% ../notebooks/14_controlled_processes.ipynb #controlled-shared-joint-emission-law
def _emission_law(p):
    """Joint Merton cumulants and multiplier covariance under one jump clock."""
    mu, sigma, jm, js = [
        np.asarray(p[key]) for key in ("mu", "sigma", "jump_mean", "jump_sigma")
    ]
    rate, dt = p["jump_rate"], p["dt"]
    diffusion = np.outer(sigma, sigma) * p["correlation"]
    jump = np.outer(js, js) * p["jump_correlation"]
    kappa = np.expm1(jm + 0.5 * js**2)
    drift = (mu - 0.5 * sigma**2 - rate * kappa) * dt
    mean = drift + rate * dt * jm
    covariance = dt * (diffusion + rate * (jump + np.outer(jm, jm)))
    growth = _exp(mu * dt, "Expected price multiplier")
    jump_growth = _exp(jm + 0.5 * js**2, "Expected jump multiplier")
    cross_jump = np.outer(jump_growth, jump_growth) * np.expm1(jump) + np.outer(
        kappa, kappa
    )
    spread = dt * (diffusion + rate * cross_jump)
    growth_cov = np.outer(growth, growth) * np.expm1(spread)
    _finite([drift, mean], "Return moments")
    _finite(covariance, "Return covariance")
    _finite(growth_cov, "Price multiplier covariance")
    return dict(
        drift=drift,
        mean=mean,
        covariance=covariance,
        growth=growth,
        growth_covariance=growth_cov,
        spread=spread,
        diffusion_factor=_factor(diffusion * dt),
        jump_factor=_factor(jump),
        jump_mean=jm,
        intensity=rate * dt,
    )


